            ctx.putImageData(imgdata, 0, 0)
            if (w > h) {
                var x0 = 0
                var y0 = mod.canvas.height * .5 * (1 - h / w)
                var wd = mod.canvas.width
                var hd = mod.canvas.width * h / w
