        var sort = mod.sort.checked
        for (var segnew = 0; segnew < path.length; ++segnew) {
            if (conventional)
                path[segnew].reverse()
            if (mod.path.length == 0)
                mod.path.splice(0, 0, path[segnew])
            else if (sort) {
                var xnew = path[segnew][0][0]
                var ynew = path[segnew][0][1]
