                triangle.setAttribute('points', x2 + ',' + y2 + ' ' + (x2 - nx + tx) + ',' + (y2 - ny + ty) +
                    ' ' + (x2 - nx - tx) + ',' + (y2 - ny - ty))
                triangle.setAttribute('fill', 'red')
                g.appendChild(triangle)
            }
        }
    }
