            var input = new Uint8ClampedArray(evt.data.buffer)
            var northsouth = 0
            var north = 128
            var south = 64
            var eastwest = 1
            var east = 128
            var west = 64
            var startstop = 2
            var start = 128
            var stop = 64
            var path = []
            //
            // edge follower
            //
            function follow_edges(row, col) {
