         x = xoffset+scale*mod.path[seg][pt][0]
         y = yoffset+scale*mod.path[seg][pt][1]
         z = zoffset+scale*mod.path[seg][pt][2]
         str += "Z"+x.toFixed(0)+","+y.toFixed(0)+","+z.toFixed(0)+";\n"
         total_sec += toolxyz.move(x, y, z) / (mod.units * speed)
         }
