    }
    //
    // load from URL
    //
    function load_from_url(url) {
        fetch(url).then(function(r) {
            if (!r.ok) { set_prompt('error: could not fetch ' + url); return }
            return r.arrayBuffer()
        }).then(function(buf) {
            if (!buf) return
            file_name = url.split('/').pop()
            mod.name.nodeValue = file_name
